OUT=ROOT/'manual operativo/recursos';OUT.mkdir(parents=True,exist_ok=True)
PDF=OUT/'Flujo_completo_del_ERP.pdf'
c=canvas.Canvas(str(PDF),pagesize=(1100,780));c.setTitle('ERP JM - Flujo completo de funcionamiento');c.setAuthor('ERP JM')

def page(n,title,sub):
 c.setFillColor(white);c.rect(0,0,1100,780,fill=1,stroke=0);c.setFillColor(HexColor(NAVY));c.rect(0,694,1100,86,fill=1,stroke=0);c.setFillColor(white);c.setFont('Helvetica-Bold',23);c.drawString(30,744,f'{n:02d}  {title}');c.setFont('Helvetica',11.5);c.drawString(30,720,sub)
 label(c,30,18,'ERP JM | Piloto ca0ce1e | 03 nov 2026 | Datos de demostración, sin operaciones reales',9,GREY)
 label(c,30,40,'Leyenda: + entrada física | - salida física | 0 sin movimiento | CXP proveedor | CXC cliente',10,GREY)

def end():c.showPage()
def B(x,y,w,h,t,b='',color=BLUE):box(c,x,y,w,h,t,b,color,font=12)
def A(x1,y1,x2,y2,color=GREY):arrow(c,x1,y1,x2,y2,color)
def note(y,text,color=INK):label(c,30,y,text,11,color)
def seq(items,y=594,x=30,w=235,h=66,color=BLUE):
 for i,(title,body) in enumerate(items):
  pos=x+i*(w+30);B(pos,y,w,h,title,body,color)
  if i<len(items)-1:A(pos+w,y+h/2,pos+w+30,y+h/2,color)
def grid(rows,y=180,widths=None):
 widths=widths or [1040/len(rows[0])]*len(rows[0]);height=25
 for i,row in enumerate(rows):
  x=30
  for w,value in zip(widths,row):
   c.setFillColor(HexColor(NAVY if i==0 else ('#eff5f9' if i%2 else '#ffffff')));c.setStrokeColor(HexColor('#cad6e0'));c.rect(x,y-i*height,w,height,fill=1,stroke=1);c.setFont('Helvetica-Bold' if i==0 else 'Helvetica',10.5);c.setFillColor(white if i==0 else HexColor(INK));c.drawString(x+7,y-i*height+8,str(value));x+=w

